Not Recommended:
function void set_message_attribute_int(int handle,
string attrName, int value);
string attr_name = "";
$sformat(attr_name, "+name+%s", attrName);
$fsdbTrans_add_attribute(handle, value, attr_name,
"+radix+dec", "+numbit+32");
endfunction

